// ProcessProduction is the resolver for the processProduction field.
func (r *mutationResolver) ProcessProduction(ctx context.Context, input model.ProcessProductionInput) ([]*model.InventoryTransaction, error) {
	userID, err := auth.RequireUser(ctx)
	if err != nil {
		return nil, err
	}
	// Validate both quantities.
	validQuantity := func(q float64) bool {
		return !math.IsNaN(q) &&
			!math.IsInf(q, 0) &&
			q > 0 &&
			q <= 9999999999.99 &&
			math.Abs(q*100-math.Round(q*100)) <= 1e-7
	}

	if !validQuantity(input.RawQuantity) || !validQuantity(input.FinishedQuantity) {
		return nil, fmt.Errorf("quantities must be positive and have at most two decimal places")
	}

	rawProductID, err := strconv.ParseInt(input.RawProductID, 10, 64)
	if err != nil || rawProductID <= 0 {
		return nil, fmt.Errorf("invalid raw product ID")
	}

	finishedProductID, err := strconv.ParseInt(input.FinishedProductID, 10, 64)
	if err != nil || finishedProductID <= 0 {
		return nil, fmt.Errorf("invalid finished product ID")
	}

	if rawProductID == finishedProductID {
		return nil, fmt.Errorf("raw product and finished product must be different")
	}

	locationID, err := strconv.ParseInt(input.LocationID, 10, 64)
	if err != nil || locationID <= 0 {
		return nil, fmt.Errorf("invalid location ID")
	}

	rawQuantity := strconv.FormatFloat(input.RawQuantity, 'f', 2, 64)
	finishedQuantity := strconv.FormatFloat(input.FinishedQuantity, 'f', 2, 64)

	// Both inventory changes must succeed together.
	tx, err := r.DB.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("begin production transaction: %w", err)
	}
	defer tx.Rollback(ctx)

	// Consume raw material only if enough stock exists.
	var remainingRawQuantity string

	err = tx.QueryRow(ctx, `
        UPDATE inventory
        SET quantity = quantity - $3::numeric,
            updated_at = NOW()
        WHERE product_id = $1
          AND location_id = $2
          AND quantity >= $3::numeric
        RETURNING quantity::text
    `, rawProductID, locationID, rawQuantity).Scan(&remainingRawQuantity)

	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, fmt.Errorf("insufficient raw material inventory")
		}
		return nil, fmt.Errorf("consume raw material: %w", err)
	}

	// Add finished goods to inventory.
	_, err = tx.Exec(ctx, `
        INSERT INTO inventory (product_id, location_id, quantity)
        VALUES ($1, $2, $3::numeric)
        ON CONFLICT (product_id, location_id)
        DO UPDATE SET
            quantity = inventory.quantity + EXCLUDED.quantity,
            updated_at = NOW()
    `, finishedProductID, locationID, finishedQuantity)

	if err != nil {
		return nil, fmt.Errorf("add finished goods: %w", err)
	}

	// Record both movements in transaction history.
	type movement struct {
		productID int64
		quantity  float64
		direction string
	}

	movements := []movement{
		{rawProductID, input.RawQuantity, "CONSUMED"},
		{finishedProductID, input.FinishedQuantity, "PRODUCED"},
	}

	transactions := make([]*model.InventoryTransaction, 0, 2)

	for _, movement := range movements {
		notes := "Production " + movement.direction
		if input.Notes != nil && strings.TrimSpace(*input.Notes) != "" {
			notes += "\nNotes: " + strings.TrimSpace(*input.Notes)
		}

		quantityText := strconv.FormatFloat(movement.quantity, 'f', 2, 64)

		var transactionID int64
		var createdAt time.Time

		err = tx.QueryRow(ctx, `
			INSERT INTO inventory_transactions (
				product_id,
				location_id,
				user_id,
				transaction_type,
				quantity,
				reference,
				notes
			)
			VALUES ($1, $2, $3, 'PRODUCTION', $4::numeric, $5, $6)
			RETURNING id, created_at
		`, movement.productID, locationID, userID, quantityText, input.Reference, notes).
			Scan(&transactionID, &createdAt)

		if err != nil {
			return nil, fmt.Errorf("record production movement: %w", err)
		}

		transactions = append(transactions, &model.InventoryTransaction{
			ID:              strconv.FormatInt(transactionID, 10),
			ProductID:       strconv.FormatInt(movement.productID, 10),
			LocationID:      strconv.FormatInt(locationID, 10),
			TransactionType: "PRODUCTION",
			Quantity:        movement.quantity,
			Reference:       input.Reference,
			Notes:           &notes,
			CreatedAt:       createdAt.Format(time.RFC3339),
		})
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("commit production transaction: %w", err)
	}

	return transactions, nil
}

// TransferInventory is the resolver for the transferInventory field.
func (r *mutationResolver) TransferInventory(ctx context.Context, input model.TransferInventoryInput) (*model.InventoryTransaction, error) {
	userID, err := auth.RequireUser(ctx)
	if err != nil {
		return nil, err
	}
	// 1. Validate the transfer quantity.
	quantity := input.Quantity

	if math.IsNaN(quantity) ||
		math.IsInf(quantity, 0) ||
		quantity <= 0 ||
		quantity > 9999999999.99 ||
		math.Abs(quantity*100-math.Round(quantity*100)) > 1e-7 {
		return nil, fmt.Errorf("quantity must be positive and have at most two decimal places")
	}

	// 2. Validate product and location IDs.
	productID, err := strconv.ParseInt(input.ProductID, 10, 64)
	if err != nil || productID <= 0 {
		return nil, fmt.Errorf("invalid product ID")
	}

	fromLocationID, err := strconv.ParseInt(input.FromLocationID, 10, 64)
	if err != nil || fromLocationID <= 0 {
		return nil, fmt.Errorf("invalid source location ID")
	}

	toLocationID, err := strconv.ParseInt(input.ToLocationID, 10, 64)
	if err != nil || toLocationID <= 0 {
		return nil, fmt.Errorf("invalid destination location ID")
	}

	if fromLocationID == toLocationID {
		return nil, fmt.Errorf("source and destination locations must be different")
	}

	quantityText := strconv.FormatFloat(quantity, 'f', 2, 64)

	// 3. Start a database transaction.
	tx, err := r.DB.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("begin inventory transfer: %w", err)
	}
	defer tx.Rollback(ctx)

	// 4. Deduct stock from the source location.
	var remainingQuantity string

	err = tx.QueryRow(ctx, `
        UPDATE inventory
        SET quantity = quantity - $3::numeric,
            updated_at = NOW()
        WHERE product_id = $1
          AND location_id = $2
          AND quantity >= $3::numeric
        RETURNING quantity::text
    `, productID, fromLocationID, quantityText).Scan(&remainingQuantity)

	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, fmt.Errorf("insufficient inventory at source location")
		}
		return nil, fmt.Errorf("deduct source inventory: %w", err)
	}

	// 5. Add stock to the destination location.
	_, err = tx.Exec(ctx, `
        INSERT INTO inventory (product_id, location_id, quantity)
        VALUES ($1, $2, $3::numeric)
        ON CONFLICT (product_id, location_id)
        DO UPDATE SET
            quantity = inventory.quantity + EXCLUDED.quantity,
            updated_at = NOW()
    `, productID, toLocationID, quantityText)

	if err != nil {
		return nil, fmt.Errorf("add destination inventory: %w", err)
	}

	// 6. Record the transfer in transaction history.
	var transactionID int64
	var createdAt time.Time

	err = tx.QueryRow(ctx, `
    INSERT INTO inventory_transactions (
        product_id,
        location_id,
        from_location_id,
        to_location_id,
        user_id,
        transaction_type,
        quantity,
        reference,
        notes
    )
    VALUES ($1, $2, $3, $4, $5, 'TRANSFER', $6::numeric, $7, $8)
    RETURNING id, created_at
`,
		productID,
		fromLocationID,
		fromLocationID,
		toLocationID,
		userID,
		quantityText,
		input.Reference,
		input.Notes,
	).Scan(&transactionID, &createdAt)

	if err != nil {
		return nil, fmt.Errorf("record inventory transfer: %w", err)
	}

	// 7. Commit all changes together.
	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("commit inventory transfer: %w", err)
	}

	// 8. Return the recorded transfer.
	fromID := strconv.FormatInt(fromLocationID, 10)
	toID := strconv.FormatInt(toLocationID, 10)

	return &model.InventoryTransaction{
		ID:              strconv.FormatInt(transactionID, 10),
		ProductID:       strconv.FormatInt(productID, 10),
		LocationID:      fromID,
		FromLocationID:  &fromID,
		ToLocationID:    &toID,
		TransactionType: "TRANSFER",
		Quantity:        quantity,
		Reference:       input.Reference,
		Notes:           input.Notes,
		CreatedAt:       createdAt.Format(time.RFC3339),
	}, nil
}

// RegisterUser is the resolver for the registerUser field.
func (r *mutationResolver) RegisterUser(ctx context.Context, input model.RegisterUserInput) (*model.User, error) {
	// Validate the user's name.
	name := strings.TrimSpace(input.Name)
	if name == "" || len(name) > 100 {
		return nil, fmt.Errorf("name must be between 1 and 100 characters")
	}

	// Normalize and validate the email address.
	email := strings.ToLower(strings.TrimSpace(input.Email))
	parsedEmail, err := mail.ParseAddress(email)
	if err != nil || parsedEmail.Address != email || len(email) > 254 {
		return nil, fmt.Errorf("invalid email address")
	}

	// Validate password length before hashing.
	if len(input.Password) < 8 || len(input.Password) > 72 {
		return nil, fmt.Errorf("password must be between 8 and 72 bytes")
	}

	// Hash the password securely using bcrypt.
	passwordHash, err := bcrypt.GenerateFromPassword(
		[]byte(input.Password),
		bcrypt.DefaultCost,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to secure password")
	}

	// Insert the new user into PostgreSQL.
	var userID int64
	var createdAt time.Time

	err = r.DB.QueryRow(ctx, `
        INSERT INTO users (name, email, password_hash)
        VALUES ($1, $2, $3)
        RETURNING id, created_at
    `, name, email, string(passwordHash)).Scan(&userID, &createdAt)

	if err != nil {
		var pgErr *pgconn.PgError

		if errors.As(err, &pgErr) && pgErr.Code == "23505" {
			return nil, fmt.Errorf("an account with this email already exists")
		}

		return nil, fmt.Errorf("failed to register user")
	}

	return &model.User{
		ID:        strconv.FormatInt(userID, 10),
		Name:      name,
		Email:     email,
		CreatedAt: createdAt.Format(time.RFC3339),
	}, nil
}

// Login is the resolver for the login field.
func (r *mutationResolver) Login(ctx context.Context, input model.LoginInput) (*model.AuthPayload, error) {
	email := strings.ToLower(strings.TrimSpace(input.Email))

	// Retrieve the user and stored password hash.
	var userID int64
	var name, storedEmail, passwordHash string
	var createdAt time.Time

	err := r.DB.QueryRow(ctx, `
        SELECT id, name, email, password_hash, created_at
        FROM users
        WHERE email = $1
    `, email).Scan(
		&userID,
		&name,
		&storedEmail,
		&passwordHash,
		&createdAt,
	)

	// Use a generic error to avoid revealing whether an email exists.
	if err != nil {
		return nil, fmt.Errorf("invalid email or password")
	}

	// Verify the submitted password against the stored bcrypt hash.
	err = bcrypt.CompareHashAndPassword(
		[]byte(passwordHash),
		[]byte(input.Password),
	)
	if err != nil {
		return nil, fmt.Errorf("invalid email or password")
	}

	// Read the signing secret from the environment.
	secret := os.Getenv("JWT_SECRET")
	if len(secret) < 32 {
		return nil, fmt.Errorf("authentication is not configured")
	}

	// Generate a JWT that expires after 24 hours.
	now := time.Now()
	claims := jwt.RegisteredClaims{
		Subject:   strconv.FormatInt(userID, 10),
		IssuedAt:  jwt.NewNumericDate(now),
		ExpiresAt: jwt.NewNumericDate(now.Add(24 * time.Hour)),
	}

	token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)

	signedToken, err := token.SignedString([]byte(secret))
	if err != nil {
		return nil, fmt.Errorf("failed to generate authentication token")
	}

	return &model.AuthPayload{
		Token: signedToken,
		User: &model.User{
			ID:        strconv.FormatInt(userID, 10),
			Name:      name,
			Email:     storedEmail,
			CreatedAt: createdAt.Format(time.RFC3339),
		},
	}, nil
}

// UpdateProductThreshold is the resolver for the updateProductThreshold field.
func (r *mutationResolver) UpdateProductThreshold(ctx context.Context, input model.UpdateProductThresholdInput) (*model.Product, error) {
	_, err := auth.RequireUser(ctx)
	if err != nil {
		return nil, err
	}

	productID, err := strconv.ParseInt(input.ProductID, 10, 64)
	if err != nil || productID <= 0 {
		return nil, fmt.Errorf("invalid product ID")
	}

	threshold := input.LowStockThreshold

	if math.IsNaN(threshold) ||
		math.IsInf(threshold, 0) ||
		threshold < 0 ||
		threshold > 9999999999.99 ||
		math.Abs(threshold*100-math.Round(threshold*100)) > 1e-7 {
		return nil, fmt.Errorf("low stock threshold must be non-negative and have at most two decimal places")
	}

	var id int64
	var sku, name, unit string
	var description *string
	var categoryID *int64
	var updatedThreshold float64

	err = r.DB.QueryRow(
		ctx,
		`UPDATE products
         SET low_stock_threshold = $1,
             updated_at = NOW()
         WHERE id = $2
         RETURNING id, sku, name, description, category_id,
                   unit, low_stock_threshold`,
		threshold,
		productID,
	).Scan(
		&id,
		&sku,
		&name,
		&description,
		&categoryID,
		&unit,
		&updatedThreshold,
	)

	if errors.Is(err, pgx.ErrNoRows) {
		return nil, fmt.Errorf("product not found")
	}
	if err != nil {
		return nil, fmt.Errorf("update product threshold: %w", err)
	}

	var categoryIDString *string
	if categoryID != nil {
		value := strconv.FormatInt(*categoryID, 10)
		categoryIDString = &value
	}

	return &model.Product{
		ID:                strconv.FormatInt(id, 10),
		Sku:               sku,
		Name:              name,
		Description:       description,
		CategoryID:        categoryIDString,
		Unit:              unit,
		LowStockThreshold: updatedThreshold,
	}, nil
}

// Categories is the resolver for the categories field.
func (r *queryResolver) Categories(ctx context.Context) ([]*model.Category, error) {
	rows, err := r.DB.Query(
		ctx,
		"SELECT id, name FROM categories ORDER BY id",
	)
	if err != nil {
		return nil, fmt.Errorf("fetch categories: %w", err)
	}
	defer rows.Close()

	categories := make([]*model.Category, 0)

	for rows.Next() {
		var id int64
		var name string

		if err := rows.Scan(&id, &name); err != nil {
			return nil, fmt.Errorf("scan category: %w", err)
		}

		categories = append(categories, &model.Category{
			ID:   strconv.FormatInt(id, 10),
			Name: name,
		})
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate categories: %w", err)
	}

	return categories, nil
}

